export function wordWidth(word,scale=1){return [...word.toLowerCase()].reduce((n,c)=>n+(LETTERS[c]?.width??12)+6,0)*scale;}
export function wordPaths(word,x,baseline,scale=1,attributes=''){
 let offset=0;const pieces=[];
 for(const char of word.toLowerCase()){
  const glyph=LETTERS[char];if(glyph){pieces.push(`<g transform="translate(${(x+offset*scale).toFixed(2)},${baseline.toFixed(2)}) scale(${scale})">${glyph.paths.map(d=>`<path d="${d}"/>`).join('')}</g>`);}
  offset+=(glyph?.width??12)+6;
 }
 return `<g class="lettering" ${attributes}>${pieces.join('')}</g>`;
}
